import { describe, expect, it, vi, beforeEach } from 'vitest'
import { parsePackageParams } from '#server/utils/parse-package-params'
import { NPM_MISSING_README_SENTINEL } from '#shared/utils/constants'

// Mock Nitro globals before importing the module
vi.stubGlobal('defineCachedFunction', (fn: Function) => fn)
const $fetchMock = vi.fn()
vi.stubGlobal('$fetch', $fetchMock)
vi.stubGlobal('parsePackageParams', parsePackageParams)

const fetchNpmPackageMock = vi.fn()
vi.stubGlobal('fetchNpmPackage', fetchNpmPackageMock)

const parseRepositoryInfoMock = vi.fn()
vi.stubGlobal('parseRepositoryInfo', parseRepositoryInfoMock)

const { fetchReadmeFromJsdelivr, isStandardReadme, resolvePackageReadmeSource } =
  await import('#server/utils/readme-loaders')

describe('isStandardReadme', () => {
  it('returns true for standard README filenames', () => {
    expect(isStandardReadme('README.md')).toBe(true)
    expect(isStandardReadme('readme.md')).toBe(true)
    expect(isStandardReadme('Readme.md')).toBe(true)
    expect(isStandardReadme('README')).toBe(true)
    expect(isStandardReadme('readme')).toBe(true)
    expect(isStandardReadme('README.markdown')).toBe(true)
    expect(isStandardReadme('readme.markdown')).toBe(true)
  })

  it('returns false for non-standard filenames', () => {
    expect(isStandardReadme('CONTRIBUTING.md')).toBe(false)
    expect(isStandardReadme('README.txt')).toBe(false)
    expect(isStandardReadme('readme.rst')).toBe(false)
    expect(isStandardReadme(undefined)).toBe(false)
    expect(isStandardReadme('')).toBe(false)
  })
})

describe('fetchReadmeFromJsdelivr', () => {
  beforeEach(() => {
    vi.unstubAllGlobals()
    vi.stubGlobal('defineCachedFunction', (fn: Function) => fn)
    vi.stubGlobal('$fetch', $fetchMock)
    vi.stubGlobal('parsePackageParams', parsePackageParams)
    vi.stubGlobal('fetchNpmPackage', fetchNpmPackageMock)
    vi.stubGlobal('parseRepositoryInfo', parseRepositoryInfoMock)
  })

  it('returns content when first filename succeeds', async () => {
    const content = '# Package'
    const fetchMock = vi.fn().mockResolvedValue({
      ok: true,
      text: async () => content,
    })
    vi.stubGlobal('fetch', fetchMock)

    const result = await fetchReadmeFromJsdelivr('some-pkg', ['README.md'])

    expect(result).toBe(content)
    expect(fetchMock).toHaveBeenCalledWith('https://cdn.jsdelivr.net/npm/some-pkg/README.md')
  })

  it('includes version in URL when version is passed', async () => {
    const fetchMock = vi.fn().mockResolvedValue({
      ok: true,
      text: async () => '',
    })
    vi.stubGlobal('fetch', fetchMock)

    await fetchReadmeFromJsdelivr('pkg', ['README.md'], '1.2.3')

    expect(fetchMock).toHaveBeenCalledWith('https://cdn.jsdelivr.net/npm/pkg@1.2.3/README.md')
  })

  it('returns null when all fetches fail', async () => {
    const fetchMock = vi.fn().mockResolvedValue({ ok: false })
    vi.stubGlobal('fetch', fetchMock)

    const result = await fetchReadmeFromJsdelivr('pkg', ['README.md', 'readme.md'])

    expect(result).toBeNull()
    expect(fetchMock).toHaveBeenCalledTimes(2)
  })

  it('starts a small batch of candidate fetches in parallel', async () => {
    let resolveReadmeMd!: (value: { ok: false }) => void
    let resolveLowercase!: (value: { ok: false }) => void
    let resolveReadme!: (value: { ok: true; text: () => Promise<string> }) => void

    const fetchMock = vi.fn((url: string) => {
      if (url.endsWith('/README.md')) {
        return new Promise(resolve => {
          resolveReadmeMd = resolve
        })
      }

      if (url.endsWith('/readme.md')) {
        return new Promise(resolve => {
          resolveLowercase = resolve
        })
      }

      if (url.endsWith('/README')) {
        return new Promise(resolve => {
          resolveReadme = resolve
        })
      }

      return Promise.resolve({ ok: false })
    })
    vi.stubGlobal('fetch', fetchMock)

    const resultPromise = fetchReadmeFromJsdelivr('pkg', [
      'README.md',
      'readme.md',
      'README',
      'readme',
    ])

    expect(fetchMock).toHaveBeenCalledTimes(3)
    expect(fetchMock.mock.calls.map(([url]) => url)).toEqual([
      'https://cdn.jsdelivr.net/npm/pkg/README.md',
      'https://cdn.jsdelivr.net/npm/pkg/readme.md',
      'https://cdn.jsdelivr.net/npm/pkg/README',
    ])

    resolveReadmeMd({ ok: false })
    resolveLowercase({ ok: false })
    resolveReadme({
      ok: true,
      text: async () => '# Package',
    })

    await expect(resultPromise).resolves.toBe('# Package')
    expect(fetchMock).toHaveBeenCalledTimes(3)
  })

  it('reads only the matched successful response body', async () => {
    const firstTextMock = vi.fn().mockResolvedValue('# First')
    const secondTextMock = vi.fn().mockResolvedValue('# Second')
    const secondCancelMock = vi.fn().mockResolvedValue(undefined)
    const fetchMock = vi
      .fn()
      .mockResolvedValueOnce({
        ok: true,
        text: firstTextMock,
      })
      .mockResolvedValueOnce({
        ok: true,
        text: secondTextMock,
        body: {
          cancel: secondCancelMock,
        },
      })
    vi.stubGlobal('fetch', fetchMock)

    const result = await fetchReadmeFromJsdelivr('pkg', ['README.md', 'readme.md'])

    expect(result).toBe('# First')
    expect(firstTextMock).toHaveBeenCalledTimes(1)
    expect(secondTextMock).not.toHaveBeenCalled()
    expect(secondCancelMock).toHaveBeenCalledTimes(1)
  })
})

describe('resolvePackageReadmeSource', () => {
  beforeEach(() => {
    fetchNpmPackageMock.mockReset()
    parseRepositoryInfoMock.mockReset()
  })

  it('returns markdown and repoInfo when package has valid npm readme (latest)', async () => {
    const markdown = '# Hello'
    fetchNpmPackageMock.mockResolvedValue({
      readme: markdown,
      readmeFilename: 'README.md',
      repository: { url: 'https://github.com/u/r' },
      versions: {},
    })
    parseRepositoryInfoMock.mockReturnValue({
      provider: 'github',
      owner: 'u',
      repo: 'r',
      rawBaseUrl: 'https://raw.githubusercontent.com/u/r/HEAD',
      blobBaseUrl: 'https://github.com/u/r/blob/HEAD',
    })

    const result = await resolvePackageReadmeSource('some-pkg')

    expect(result).toMatchObject({
      packageName: 'some-pkg',
      version: undefined,
      markdown,
      repoInfo: { provider: 'github', owner: 'u', repo: 'r' },
    })
    expect(fetchNpmPackageMock).toHaveBeenCalledWith('some-pkg')
  })

  it('returns markdown from version when packagePath includes version', async () => {
    const markdown = '# Version readme'
    fetchNpmPackageMock.mockResolvedValue({
      readme: 'latest readme',
      readmeFilename: 'README.md',
      repository: undefined,
      versions: {
        '1.0.0': { readme: markdown, readmeFilename: 'README.md' },
      },
    })
    parseRepositoryInfoMock.mockReturnValue(undefined)

    const result = await resolvePackageReadmeSource('some-pkg/v/1.0.0')

    expect(result).toMatchObject({
      packageName: 'some-pkg',
      version: '1.0.0',
      markdown,
    })
  })

  it('falls back to jsdelivr when npm readme is missing sentinel', async () => {
    const jsdelivrContent = '# From CDN'
    fetchNpmPackageMock.mockResolvedValue({
      readme: NPM_MISSING_README_SENTINEL,
      readmeFilename: 'README.md',
      repository: undefined,
      versions: {},
    })
    parseRepositoryInfoMock.mockReturnValue(undefined)
    const fetchMock = vi.fn().mockResolvedValue({
      ok: true,
      text: async () => jsdelivrContent,
    })
    vi.stubGlobal('fetch', fetchMock)

    const result = await resolvePackageReadmeSource('pkg')

    expect(result).toMatchObject({
      packageName: 'pkg',
      markdown: jsdelivrContent,
      repoInfo: undefined,
    })
    expect(fetchMock).toHaveBeenCalled()
  })

  it('falls back to jsdelivr when readmeFilename is not standard', async () => {
    const jsdelivrContent = '# From CDN'
    fetchNpmPackageMock.mockResolvedValue({
      readme: 'content',
      readmeFilename: 'DOCS.md',
      repository: undefined,
      versions: {},
    })
    parseRepositoryInfoMock.mockReturnValue(undefined)
    const fetchMock = vi.fn().mockResolvedValue({
      ok: true,
      text: async () => jsdelivrContent,
    })
    vi.stubGlobal('fetch', fetchMock)

    const result = await resolvePackageReadmeSource('pkg')

    expect(result).toMatchObject({ markdown: jsdelivrContent })
    expect(fetchMock).toHaveBeenNthCalledWith(1, 'https://cdn.jsdelivr.net/npm/pkg/DOCS.md')
  })

  it('tries a provided readmeFilename before starting the fallback batch', async () => {
    let resolveDocs!: (value: { ok: false }) => void
    let resolveReadmeMd!: (value: { ok: false }) => void
    let resolveLowercase!: (value: { ok: false }) => void
    let resolveReadmeCase!: (value: { ok: true; text: () => Promise<string> }) => void

    fetchNpmPackageMock.mockResolvedValue({
      readme: undefined,
      readmeFilename: 'DOCS.md',
      repository: undefined,
      versions: {},
    })
    parseRepositoryInfoMock.mockReturnValue(undefined)

    const fetchMock = vi.fn((url: string) => {
      if (url.endsWith('/DOCS.md')) {
        return new Promise(resolve => {
          resolveDocs = resolve
        })
      }

      if (url.endsWith('/README.md')) {
        return new Promise(resolve => {
          resolveReadmeMd = resolve
        })
      }

      if (url.endsWith('/readme.md')) {
        return new Promise(resolve => {
          resolveLowercase = resolve
        })
      }

      if (url.endsWith('/Readme.md')) {
        return new Promise(resolve => {
          resolveReadmeCase = resolve
        })
      }

      return Promise.resolve({ ok: false })
    })
    vi.stubGlobal('fetch', fetchMock)

    const resultPromise = resolvePackageReadmeSource('pkg')

    await new Promise(resolve => setTimeout(resolve, 0))
    expect(fetchMock).toHaveBeenCalledTimes(1)
    expect(fetchMock).toHaveBeenNthCalledWith(1, 'https://cdn.jsdelivr.net/npm/pkg/DOCS.md')

    resolveDocs({ ok: false })

    await new Promise(resolve => setTimeout(resolve, 0))
    expect(fetchMock).toHaveBeenCalledTimes(4)
    expect(fetchMock.mock.calls.slice(1).map(([url]) => url)).toEqual([
      'https://cdn.jsdelivr.net/npm/pkg/README.md',
      'https://cdn.jsdelivr.net/npm/pkg/readme.md',
      'https://cdn.jsdelivr.net/npm/pkg/Readme.md',
    ])

    resolveReadmeMd({ ok: false })
    resolveLowercase({ ok: false })
    resolveReadmeCase({
      ok: true,
      text: async () => '# From fallback batch',
    })

    await expect(resultPromise).resolves.toMatchObject({
      packageName: 'pkg',
      markdown: '# From fallback batch',
      repoInfo: undefined,
    })
  })

  it('returns undefined markdown when no content and jsdelivr fails', async () => {
    fetchNpmPackageMock.mockResolvedValue({
      readme: undefined,
      readmeFilename: undefined,
      repository: undefined,
      versions: {},
    })
    parseRepositoryInfoMock.mockReturnValue(undefined)
    const fetchMock = vi.fn().mockResolvedValue({ ok: false })
    vi.stubGlobal('fetch', fetchMock)

    const result = await resolvePackageReadmeSource('pkg')

    expect(result).toMatchObject({
      packageName: 'pkg',
      version: undefined,
      markdown: undefined,
      repoInfo: undefined,
    })
  })

  it('returns undefined markdown when content is NPM_MISSING_README_SENTINEL and jsdelivr fails', async () => {
    fetchNpmPackageMock.mockResolvedValue({
      readme: NPM_MISSING_README_SENTINEL,
      readmeFilename: 'README.md',
      repository: undefined,
      versions: {},
    })
    const fetchMock = vi.fn().mockResolvedValue({ ok: false })
    vi.stubGlobal('fetch', fetchMock)

    const result = await resolvePackageReadmeSource('pkg')

    expect(result).toMatchObject({
      packageName: 'pkg',
      markdown: undefined,
      repoInfo: undefined,
    })
  })

  it('fetches from jsdelivr when packument readme exceeds truncation threshold', async () => {
    const truncatedReadme = 'x'.repeat(64_000)
    const fullReadme = 'x'.repeat(80_000)
    fetchNpmPackageMock.mockResolvedValue({
      'readme': truncatedReadme,
      'readmeFilename': 'README.md',
      'repository': undefined,
      'versions': {},
      'dist-tags': { latest: '1.0.0' },
    })
    parseRepositoryInfoMock.mockReturnValue(undefined)
    const fetchMock = vi.fn().mockResolvedValue({
      ok: true,
      text: async () => fullReadme,
    })
    vi.stubGlobal('fetch', fetchMock)

    const result = await resolvePackageReadmeSource('pkg')

    expect(result).toMatchObject({ markdown: fullReadme })
    expect(fetchMock).toHaveBeenCalled()
  })

  it('uses package repository for repoInfo when markdown is present', async () => {
    fetchNpmPackageMock.mockResolvedValue({
      readme: '# Hi',
      readmeFilename: 'README.md',
      repository: { url: 'https://github.com/a/b' },
      versions: {},
    })
    const repoInfo = {
      provider: 'github' as const,
      owner: 'a',
      repo: 'b',
      rawBaseUrl: 'https://raw.githubusercontent.com/a/b/HEAD',
      blobBaseUrl: 'https://github.com/a/b/blob/HEAD',
    }
    parseRepositoryInfoMock.mockReturnValue(repoInfo)

    const result = await resolvePackageReadmeSource('pkg')

    expect(result?.repoInfo).toEqual(repoInfo)
    expect(parseRepositoryInfoMock).toHaveBeenCalledWith({ url: 'https://github.com/a/b' })
  })
})

import type { RepositoryInfo } from '#shared/utils/git-providers'
import { describe, expect, it, vi, beforeAll } from 'vitest'

// Mock the global Nuxt auto-imports before importing the module
beforeAll(() => {
  vi.stubGlobal(
    'getShikiHighlighter',
    vi.fn().mockResolvedValue({
      getLoadedLanguages: () => [],
      codeToHtml: (code: string) => `<pre><code>${code}</code></pre>`,
    }),
  )
  vi.stubGlobal(
    'useRuntimeConfig',
    vi.fn().mockReturnValue({
      imageProxySecret: 'test-secret-for-readme-tests',
    }),
  )
})

// Import after mock is set up
const { renderReadmeHtml } = await import('#server/utils/readme')

// Helper to create mock repository info
function createRepoInfo(overrides?: Partial<RepositoryInfo>): RepositoryInfo {
  return {
    provider: 'github',
    owner: 'test-owner',
    repo: 'test-repo',
    rawBaseUrl: 'https://raw.githubusercontent.com/test-owner/test-repo/HEAD',
    blobBaseUrl: 'https://github.com/test-owner/test-repo/blob/HEAD',
    ...overrides,
  }
}

describe('Playground Link Extraction', () => {
  describe('StackBlitz', () => {
    it('extracts stackblitz.com links', async () => {
      const markdown = `Check out [Demo on StackBlitz](https://stackblitz.com/github/user/repo)`
      const result = await renderReadmeHtml(markdown, 'test-pkg')

      expect(result.playgroundLinks).toHaveLength(1)
      expect(result.playgroundLinks[0]).toMatchObject({
        provider: 'stackblitz',
        providerName: 'StackBlitz',
        label: 'Demo on StackBlitz',
        url: 'https://stackblitz.com/github/user/repo',
      })
    })
  })

  describe('CodeSandbox', () => {
    it('extracts codesandbox.io links', async () => {
      const markdown = `[Try it](https://codesandbox.io/s/example-abc123)`
      const result = await renderReadmeHtml(markdown, 'test-pkg')

      expect(result.playgroundLinks).toHaveLength(1)
      expect(result.playgroundLinks[0]).toMatchObject({
        provider: 'codesandbox',
        providerName: 'CodeSandbox',
      })
    })

    it('extracts githubbox.com links as CodeSandbox', async () => {
      const markdown = `[Demo](https://githubbox.com/user/repo/tree/main/examples)`
      const result = await renderReadmeHtml(markdown, 'test-pkg')

      expect(result.playgroundLinks).toHaveLength(1)
      expect(result.playgroundLinks[0]!.provider).toBe('codesandbox')
    })

    it('extracts label from image link', async () => {
      const markdown = `[![Edit CodeSandbox](https://codesandbox.io/static/img/play-codesandbox.svg)](https://codesandbox.io/s/example-abc123)`
      const result = await renderReadmeHtml(markdown, 'test-pkg')

      expect(result.playgroundLinks).toHaveLength(1)
      expect(result.playgroundLinks[0]).toMatchObject({
        provider: 'codesandbox',
        providerName: 'CodeSandbox',
        label: 'Edit CodeSandbox',
        url: 'https://codesandbox.io/s/example-abc123',
      })
    })
  })

  describe('Other Providers', () => {
    it('extracts CodePen links', async () => {
      const markdown = `[Pen](https://codepen.io/user/pen/abc123)`
      const result = await renderReadmeHtml(markdown, 'test-pkg')

      expect(result.playgroundLinks[0]!.provider).toBe('codepen')
    })

    it('extracts Replit links', async () => {
      const markdown = `[Repl](https://replit.com/@user/project)`
      const result = await renderReadmeHtml(markdown, 'test-pkg')

      expect(result.playgroundLinks[0]!.provider).toBe('replit')
    })

    it('extracts Gitpod links', async () => {
      const markdown = `[Open in Gitpod](https://gitpod.io/#https://github.com/user/repo)`
      const result = await renderReadmeHtml(markdown, 'test-pkg')

      expect(result.playgroundLinks[0]!.provider).toBe('gitpod')
    })
  })

  describe('Multiple Links', () => {
    it('extracts multiple playground links', async () => {
      const markdown = `
- [StackBlitz](https://stackblitz.com/example1)
- [CodeSandbox](https://codesandbox.io/s/example2)
`
      const result = await renderReadmeHtml(markdown, 'test-pkg')

      expect(result.playgroundLinks).toHaveLength(2)
      expect(result.playgroundLinks[0]!.provider).toBe('stackblitz')
      expect(result.playgroundLinks[1]!.provider).toBe('codesandbox')
    })

    it('deduplicates same URL', async () => {
      const markdown = `
[Demo 1](https://stackblitz.com/example)
[Demo 2](https://stackblitz.com/example)
`
      const result = await renderReadmeHtml(markdown, 'test-pkg')

      expect(result.playgroundLinks).toHaveLength(1)
    })
  })

  describe('Non-Playground Links', () => {
    it('ignores regular GitHub links', async () => {
      const markdown = `[Repo](https://github.com/user/repo)`
      const result = await renderReadmeHtml(markdown, 'test-pkg')

      expect(result.playgroundLinks).toHaveLength(0)
    })

    it('ignores npm links', async () => {
      const markdown = `[Package](https://npmjs.com/package/test)`
      const result = await renderReadmeHtml(markdown, 'test-pkg')

      expect(result.playgroundLinks).toHaveLength(0)
    })
  })

  describe('Edge Cases', () => {
    it('returns empty array for empty content', async () => {
      const result = await renderReadmeHtml('', 'test-pkg')

      expect(result.playgroundLinks).toEqual([])
      expect(result.html).toBe('')
    })

    it('handles badge images wrapped in links', async () => {
      const markdown = `[![Open in StackBlitz](https://img.shields.io/badge/Open-StackBlitz-blue)](https://stackblitz.com/example)`
      const result = await renderReadmeHtml(markdown, 'test-pkg')

      expect(result.playgroundLinks).toHaveLength(1)
      expect(result.playgroundLinks[0]!.provider).toBe('stackblitz')
    })
  })
})

describe('Markdown File URL Resolution', () => {
  describe('with repository info', () => {
    it('resolves relative .md links to blob URL for rendered viewing', async () => {
      const repoInfo = createRepoInfo()
      const markdown = `[Contributing](./CONTRIBUTING.md)`
      const result = await renderReadmeHtml(markdown, 'test-pkg', repoInfo)

      expect(result.html).toContain(
        'href="https://github.com/test-owner/test-repo/blob/HEAD/CONTRIBUTING.md"',
      )
    })

    it('resolves relative .MD links (uppercase) to blob URL', async () => {
      const repoInfo = createRepoInfo()
      const markdown = `[Guide](./GUIDE.MD)`
      const result = await renderReadmeHtml(markdown, 'test-pkg', repoInfo)

      expect(result.html).toContain(
        'href="https://github.com/test-owner/test-repo/blob/HEAD/GUIDE.MD"',
      )
    })

    it('resolves nested relative .md links to blob URL', async () => {
      const repoInfo = createRepoInfo()
      const markdown = `[API Docs](./docs/api/reference.md)`
      const result = await renderReadmeHtml(markdown, 'test-pkg', repoInfo)

      expect(result.html).toContain(
        'href="https://github.com/test-owner/test-repo/blob/HEAD/docs/api/reference.md"',
      )
    })

    it('resolves relative .md links with query strings to blob URL', async () => {
      const repoInfo = createRepoInfo()
      const markdown = `[FAQ](./FAQ.md?ref=main)`
      const result = await renderReadmeHtml(markdown, 'test-pkg', repoInfo)

      expect(result.html).toContain(
        'href="https://github.com/test-owner/test-repo/blob/HEAD/FAQ.md?ref=main"',
      )
    })

    it('resolves relative .md links with anchors to blob URL', async () => {
      const repoInfo = createRepoInfo()
      const markdown = `[Install Section](./CONTRIBUTING.md#installation)`
      const result = await renderReadmeHtml(markdown, 'test-pkg', repoInfo)

      expect(result.html).toContain(
        'href="https://github.com/test-owner/test-repo/blob/HEAD/CONTRIBUTING.md#installation"',
      )
    })

    it('resolves non-.md files to raw URL (not blob)', async () => {
      const repoInfo = createRepoInfo()
      const markdown = `[Image](./assets/logo.png)`
      const result = await renderReadmeHtml(markdown, 'test-pkg', repoInfo)

      expect(result.html).toContain(
