/**
 * Tests for issue #1323: single-pass markdown rendering behavior.
 *
 * The core concern is that mixing markdown headings and raw HTML headings
 * must produce TOC entries, heading IDs, and duplicate-slug suffixes in
 * exact document order — the same as GitHub does.
 *
 * If the implementation processes markdown headings in one pass and HTML
 * headings in a separate (later) pass, the ordering will be wrong.
 */
describe('Issue #1323 — single-pass rendering correctness', () => {
  describe('mixed markdown + HTML headings: TOC order and IDs', () => {
    it('produces TOC entries in document order when markdown and HTML headings are interleaved', async () => {
      // This is the core scenario from the issue: HTML headings appear
      // between markdown headings. A two-pass approach would collect all
      // markdown headings first, then HTML headings — scrambling the order.
      const md = [
        '# First (markdown)',
        '',
        '<h2>Second (html)</h2>',
        '',
        '## Third (markdown)',
        '',
        '<h2>Fourth (html)</h2>',
        '',
        '## Fifth (markdown)',
      ].join('\n')

      const result = await renderReadmeHtml(md, 'test-pkg')

      // TOC must reflect exact document order
      expect(result.toc).toHaveLength(5)
      expect(result.toc[0]!.text).toBe('First (markdown)')
      expect(result.toc[1]!.text).toBe('Second (html)')
      expect(result.toc[2]!.text).toBe('Third (markdown)')
      expect(result.toc[3]!.text).toBe('Fourth (html)')
      expect(result.toc[4]!.text).toBe('Fifth (markdown)')
    })

    it('assigns duplicate-slug suffixes in document order across mixed heading types', async () => {
      // Two markdown "API" headings with an HTML "API" heading in between.
      // Correct: api, api-1, api-2 in that order.
      // If HTML headings are processed in a separate pass, the HTML one
      // could get suffix -2 while the last markdown one gets -1.
      const md = ['## API', '', '<h2>API</h2>', '', '## API'].join('\n')

      const result = await renderReadmeHtml(md, 'test-pkg')

      expect(result.toc).toHaveLength(3)
      expect(result.toc[0]!.id).toBe('user-content-api')
      expect(result.toc[1]!.id).toBe('user-content-api-1')
      expect(result.toc[2]!.id).toBe('user-content-api-2')

      // The HTML output must also have these IDs in order
      const ids = Array.from(result.html.matchAll(/id="(user-content-api(?:-\d+)?)"/g), m => m[1])
      expect(ids).toEqual(['user-content-api', 'user-content-api-1', 'user-content-api-2'])
    })

    it('does not collide when heading text already starts with user-content-', async () => {
      const md = ['# Title', '', '# user-content-title'].join('\n')

      const result = await renderReadmeHtml(md, 'test-pkg')

      const ids = Array.from(result.html.matchAll(/id="(user-content-[^"]+)"/g), m => m[1])
      expect(ids).toEqual(['user-content-title', 'user-content-user-content-title'])
      expect(new Set(ids).size).toBe(ids.length)
      expect(result.toc.map(t => t.id)).toEqual(ids)
    })

    it('heading semantic levels are sequential even when mixing heading types', async () => {
      // h1 (md) → h3, h3 (html) → should be h4 (max = lastSemantic + 1),
      // not jump to h5 or h6 because it was processed in a later pass.
      const md = ['# Title', '', '<h3>Subsection</h3>', '', '#### Deep'].join('\n')

      const result = await renderReadmeHtml(md, 'test-pkg')

      // Extract semantic tags in order from the HTML
      const tags = Array.from(result.html.matchAll(/<h(\d)/g), m => Number(m[1]))
      // h1→h3, h3→h4 (sequential after h3), h4→h5 (sequential after h4)
      expect(tags).toEqual([3, 4, 5])
    })
  })

  describe('HTML heading between markdown headings — ID and href consistency', () => {
    it('heading id and its anchor href point to the same slug', async () => {
      const md = ['# Introduction', '', '<h2>Getting Started</h2>', '', '## Installation'].join(
        '\n',
      )

      const result = await renderReadmeHtml(md, 'test-pkg')

      // For every heading, the slug used in id="user-content-{slug}" must
      // match the slug in the child anchor href="#user-content-{slug}"
      // (resolveUrl prefixes # anchors with user-content-).
      const headingPairs = [
        ...result.html.matchAll(/id="user-content-([^"]+)"[^>]*><a href="#user-content-([^"]+)">/g),
      ]
      expect(headingPairs.length).toBeGreaterThan(0)
      for (const match of headingPairs) {
        // slug portion must be identical
        expect(match[1]).toBe(match[2])
      }
    })
  })

  describe('playground links collected from HTML <a> tags in single pass', () => {
    it('collects playground links from raw HTML anchor tags', async () => {
      // Some READMEs (like eslint's sponsor section) use raw HTML <a> tags
      // instead of markdown link syntax. These must also be picked up.
      const md = [
        '# My Package',
        '',
        '<a href="https://stackblitz.com/edit/my-demo">Open in StackBlitz</a>',
        '',
        'Some text with a [CodeSandbox link](https://codesandbox.io/s/example)',
      ].join('\n')

      const result = await renderReadmeHtml(md, 'test-pkg')

      // Both playground links should be collected regardless of syntax
      const providers = result.playgroundLinks.map(l => l.provider)
      expect(providers).toContain('stackblitz')
      expect(providers).toContain('codesandbox')
    })
  })

  describe('complex real-world interleaving (atproxy-like)', () => {
    it('handles a README with HTML h1 followed by markdown h2 and mixed content', async () => {
      // Simulates a pattern like atproxy's README where h1 is HTML
      // and subsequent headings are markdown
      const md = [
        '<h1 align="center">atproxy</h1>',
        '<p align="center">A cool proxy library</p>',
        '',
        '## Features',
        '',
        '- Fast',
        '- Simple',
        '',
        '## Installation',
        '',
        '```bash',
        'npm install atproxy',
        '```',
        '',
        '<h2>Advanced Usage</h2>',
        '',
        '## API',
        '',
        '### Methods',
      ].join('\n')

      const result = await renderReadmeHtml(md, 'test-pkg')

      // TOC order must be: atproxy, Features, Installation, Advanced Usage, API, Methods
      expect(result.toc.map(t => t.text)).toEqual([
        'atproxy',
        'Features',
        'Installation',
        'Advanced Usage',
        'API',
        'Methods',
      ])

      // All IDs should be unique
      const ids = result.toc.map(t => t.id)
      expect(new Set(ids).size).toBe(ids.length)
    })

    it('keeps paragraphs and fenced code blocks when mixed with HTML headings', async () => {
      const md = [
        '<h2><code>&lt;Text&gt;</code></h2>',
        '',
        'Paragraph before code.',
        '',
        '```ts',
        'const component = "Text"',
        '```',
        '',
        'Paragraph after code.',
      ].join('\n')

      const result = await renderReadmeHtml(md, 'test-pkg')

      expect(result.html).toContain('<code>&lt;Text&gt;</code>')
      expect(result.html).toContain('<p>Paragraph before code.</p>')
      expect(result.html).toContain('const component = "Text"')
      expect(result.html).toContain('<p>Paragraph after code.</p>')
      expect(result.html).toContain('id="user-content-text"')
    })
  })
})

import type { OAuthSession } from '@atproto/oauth-client-node'
import { OAuthCallbackError } from '@atproto/oauth-client-node'
import { createError, getQuery, sendRedirect, setCookie, getCookie, deleteCookie } from 'h3'
import type { H3Event } from 'h3'
import { SLINGSHOT_HOST } from '#shared/utils/constants'
import { useServerSession } from '#server/utils/server-session'
import { handleApiError } from '#server/utils/error-handler'
import type { DidString } from '@atproto/lex'
import { Client, isAtUriString } from '@atproto/lex'
import * as app from '#shared/types/lexicons/app'
import * as blue from '#shared/types/lexicons/blue'
import { isAtIdentifierString } from '@atproto/lex'
import { scope } from '#server/utils/atproto/oauth'
import { UNSET_NUXT_SESSION_PASSWORD } from '#shared/utils/constants'
// @ts-expect-error virtual file from oauth module
import { clientUri } from '#oauth/config'

const OAUTH_REQUEST_COOKIE_PREFIX = 'atproto_oauth_req'
const slingshotClient = new Client({ service: `https://${SLINGSHOT_HOST}` })

export default defineEventHandler(async event => {
  const config = useRuntimeConfig(event)
  if (!config.sessionPassword) {
    throw createError({
      status: 500,
      message: UNSET_NUXT_SESSION_PASSWORD,
    })
  }

  const query = getQuery(event)
  const session = await useServerSession(event)

  if (query.handle) {
    // Initiate auth flow
    if (
      typeof query.handle !== 'string' ||
      (!query.handle.startsWith('https://') && !isAtIdentifierString(query.handle))
    ) {
      throw createError({
        statusCode: 400,
        message: 'Invalid handle parameter',
      })
    }

    // Validate returnTo is a safe relative path (prevent open redirect)
    // Only set cookie on initial auth request, not the callback
    let redirectPath = '/'
    try {
      const clientOrigin = new URL(clientUri).origin
      const returnToUrl = new URL(query.returnTo?.toString() || '/', clientUri)
      if (returnToUrl.origin === clientOrigin) {
        redirectPath = returnToUrl.pathname + returnToUrl.search + returnToUrl.hash
      }
    } catch {
      // Invalid URL, fall back to root
    }

    try {
      const redirectUrl = await event.context.oauthClient.authorize(query.handle, {
        scope,
        prompt: query.create ? 'create' : undefined,
        // TODO: I do not believe this is working as expected on
        // an unsupported locale on the PDS. Gives Invalid at body.ui_locales
        // Commenting out for now
        // ui_locales: query.locale?.toString(),
        state: encodeOAuthState(event, { redirectPath }),
      })

      return sendRedirect(event, redirectUrl.toString())
    } catch (error) {
      const message = error instanceof Error ? error.message : 'Failed to initiate authentication.'

      return handleApiError(error, {
        statusCode: 401,
        statusMessage: 'Unauthorized',
        message: `${message}. Please login and try again.`,
      })
    }
  } else {
    // Handle callback
    try {
      const params = new URLSearchParams(query as Record<string, string>)
      const result = await event.context.oauthClient.callback(params)
      try {
        const state = decodeOAuthState(event, result.state)
        const profile = await getMiniProfile(result.session)
        const npmxProfile = await getNpmxProfile(profile.handle, result.session)

        await session.update({
          public: profile,
          profile: npmxProfile,
        })
        return sendRedirect(event, state.redirectPath)
      } catch (error) {
        // If we are unable to cleanly handle the callback, meaning that the
        // user won't be able to use the session, we sign them out of the
        // session to prevent dangling sessions. This can happen if the state is
        // invalid (e.g. user has cookies disabled, or the state expired) or if
        // there is an issue fetching the user's profile after authentication.
        await result.session.signOut()
        throw error
      }
    } catch (error) {
      if (error instanceof OAuthCallbackError && error.state) {
        // Always decode the state, to clean up the cookie
        const state = decodeOAuthState(event, error.state)

        // user cancelled explicitly
        if (query.error === 'access_denied') {
          return sendRedirect(event, state.redirectPath)
        }
      }

      const message = error instanceof Error ? error.message : 'Authentication failed.'
      return handleApiError(error, {
        statusCode: 401,
        statusMessage: 'Unauthorized',
        message: `${message}. Please login and try again.`,
      })
    }
  }
})

type OAuthStateData = {
  redirectPath: string
}

/**
 * This function encodes the OAuth state by generating a random SID, storing it
 * in a cookie, and returning a JSON string containing the original state and
 * the SID. The cookie is used to validate the authenticity of the callback
 * request later.
 *
 * This mechanism allows to bind a particular authentication request to a
 * particular client (browser) session, providing protection against CSRF attacks
 * and ensuring that the callback is part of an ongoing authentication flow
 * initiated by the same client.
 *
 * @param event The H3 event object, used to set the cookie
 * @param state The original OAuth state to encode
 * @returns A JSON string encapsulating the original state and the generated SID
 */
function encodeOAuthState(event: H3Event, data: OAuthStateData): string {
  const id = generateRandomHexString()
  // This uses an ephemeral cookie instead of useSession() to avoid polluting
  // the session with ephemeral OAuth-specific data. The cookie is set with a
  // short expiration time to limit the window of potential misuse, and is
  // deleted immediately after validating the callback to clean up any remnants
  // of the authentication flow. Using useSession() for this would require
  // additional logic to clean up the session in case of expired ephemeral data.

  // We use the id as cookie name to allow multiple concurrent auth flows (e.g.
  // user opens multiple tabs and initiates auth in both, or initiates auth,
  // waits for a while, then initiates again before completing the first one),
  // without risk of cookie value collisions between them. The cookie value is a
  // constant since the actual value doesn't matter - it's just used as a flag
  // to validate the presence of the cookie on callback.
  setCookie(event, `${OAUTH_REQUEST_COOKIE_PREFIX}_${id}`, '1', {
    maxAge: 60 * 5,
    httpOnly: true,
    // secure only if NOT in dev mode
    secure: !import.meta.dev,
    sameSite: 'lax',
    path: event.path.split('?', 1)[0],
  })

  return JSON.stringify({ data, id })
}

function generateRandomHexString(byteLength: number = 16): string {
  return Array.from(crypto.getRandomValues(new Uint8Array(byteLength)), byte =>
    byte.toString(16).padStart(2, '0'),
  ).join('')
}

/**
 * This function ensures that an oauth state was indeed encoded for the browser
 * session performing the oauth callback.
 *
 * @param event The H3 event object, used to read and delete the cookie
 * @param state The JSON string containing the original state and id
 * @returns The original OAuth state if the id is valid
 * @throws An error if the id is missing or invalid, indicating a potential issue with cookies or expired state
 */
function decodeOAuthState(event: H3Event, state: string | null): OAuthStateData {
  if (!state) {
    // May happen during transition period (if a user initiated auth flow before
    // the release with the new state handling, then tries to complete it after
    // the release).
    throw createError({
      statusCode: 400,
      message: 'Missing state parameter',
    })
  }

  // The state sting was encoded using encodeOAuthState. No need to protect
  // against JSON parsing since the StateStore should ensure it's integrity.
  const decoded = JSON.parse(state) as { data: OAuthStateData; id: string }
  const requestCookieName = `${OAUTH_REQUEST_COOKIE_PREFIX}_${decoded.id}`

  if (getCookie(event, requestCookieName) != null) {
    // The cookie will never be used again since the state store ensure unique
    // nonces, but we delete it to clean up any remnants of the authentication
    // flow.
    deleteCookie(event, requestCookieName, {
      httpOnly: true,
      secure: !import.meta.dev,
      sameSite: 'lax',
      path: event.path.split('?', 1)[0],
    })
  } else {
    throw createError({
      statusCode: 400,
      message: 'Missing authentication state. Please enable cookies and try again.',
    })
  }

  return decoded.data
}

/**
 * Fetches the mini profile for the authenticated user, including their avatar if available.
 * This is used to populate the session with basic user info after authentication.
 * @param authSession The OAuth session containing the user's DID and token info
 * @returns An object containing the user's DID, handle, PDS, and avatar URL (if available)
 */
async function getMiniProfile(authSession: OAuthSession) {
  const response = await slingshotClient.xrpcSafe(blue.microcosm.identity.resolveMiniDoc, {
    headers: { 'User-Agent': 'npmx' },
    params: { identifier: authSession.did },
  })

  if (response.success) {
    const miniDoc = response.body

    let avatar: string | undefined = await getAvatar(authSession.did, miniDoc.pds)

    return {
      ...miniDoc,
      avatar,
    }
  } else {
    //If slingshot fails we still want to set some key info we need.
    const pdsBase = (await authSession.getTokenInfo()).aud
    let avatar: string | undefined = await getAvatar(authSession.did, pdsBase)
    return {
      did: authSession.did,
      handle: 'Not available',
      pds: pdsBase,
      avatar,
    }
  }
}

/**
 * Fetch the user's profile record to get their avatar blob reference
 * @param did
 * @param pds
 * @returns
 */
async function getAvatar(did: DidString, pds: string) {
  let avatar: string | undefined
  try {
    const pdsUrl = new URL(pds)
    // Only fetch from HTTPS PDS endpoints to prevent SSRF
    if (pdsUrl.protocol === 'https:') {
      const client = new Client(pdsUrl)
      const profileResponse = await client.get(app.bsky.actor.profile, {
        repo: did,
        rkey: 'self',
      })

      const validatedResponse = app.bsky.actor.profile.main.validate(profileResponse.value)
      const cid = validatedResponse.avatar?.ref

      if (cid) {
        // Use Bluesky CDN for faster image loading
        avatar = `https://cdn.bsky.app/img/feed_thumbnail/plain/${did}/${cid}@jpeg`
      }
    }
  } catch {
    // Avatar fetch failed, continue without it
  }
  return avatar
}

async function getNpmxProfile(handle: string, authSession: OAuthSession) {
  const client = new Client(authSession)

  // get existing npmx profile OR create a new one
  const profileUri = `at://${client.did}/dev.npmx.actor.profile/self`
  if (!isAtUriString(profileUri)) {
    throw new Error(`Invalid at-uri: ${profileUri}`)
  }

  const profileResult = await slingshotClient.xrpcSafe(blue.microcosm.repo.getRecordByUri, {
    headers: { 'User-Agent': 'npmx' },
    params: { at_uri: profileUri },
  })

  if (profileResult.success) {
    return profileResult.body.value
  } else {
    const profile = {
      displayName: handle,
    }

    await client.createRecord(
      {
        $type: 'dev.npmx.actor.profile',
        ...profile,
      },
      'self',
    )

    return profile
  }
}

export default eventHandlerWithOAuthSession(async (event, oAuthSession, serverSession) => {
  // Even though the signOut also clears part of the server cache, this should be done in order
  // to let the OAuth package do any other clean up it may need
  await oAuthSession?.signOut()
  await serverSession.clear()
  return 'Session cleared'
})

import * as v from 'valibot'
import crypto from 'node:crypto'
import { CACHE_MAX_AGE_ONE_DAY, BLUESKY_API } from '#shared/utils/constants'
import { AuthorSchema } from '#shared/schemas/blog'
import { Client } from '@atproto/lex'
import type { Author, ResolvedAuthor } from '#shared/schemas/blog'
import * as app from '#shared/types/lexicons/app'

export default defineCachedEventHandler(
  async event => {
    const query = getQuery(event)
    const authorsParam = query.authors

    if (!authorsParam || typeof authorsParam !== 'string') {
      throw createError({
        statusCode: 400,
        statusMessage: 'authors query parameter is required (JSON array)',
      })
    }

    let authors: Author[]
    try {
      const parsed = JSON.parse(authorsParam)
      authors = v.parse(v.array(AuthorSchema), parsed)
    } catch (error) {
      if (error instanceof v.ValiError) {
        throw createError({
          statusCode: 400,
          statusMessage: `Invalid authors format: ${error.message}`,
        })
      }
      throw createError({
        statusCode: 400,
        statusMessage: 'authors must be valid JSON',
      })
    }

    if (!Array.isArray(authors) || authors.length === 0) {
      return { authors: [] }
    }

    const handles = authors.map(a => a.blueskyHandle).filter(handle => handle != null)

    if (handles.length === 0) {
      return {
        authors: authors.map(author => Object.assign(author, { avatar: null, profileUrl: null })),
      }
    }

    const client = new Client({ service: BLUESKY_API })
    const response = await client
      .call(app.bsky.actor.getProfiles, { actors: handles })
      .catch(() => ({ profiles: [] }))

    const avatarMap = new Map<string, string>()

    for (const profile of response.profiles) {
      if (profile.avatar) {
        avatarMap.set(profile.handle, profile.avatar)
      }
    }

    const resolvedAuthors: ResolvedAuthor[] = authors.map(author =>
      Object.assign(author, {
        avatar: author.blueskyHandle ? avatarMap.get(author.blueskyHandle) || null : null,
        profileUrl: author.blueskyHandle
          ? `https://bsky.app/profile/${author.blueskyHandle}`
          : null,
      }),
    )

    return { authors: resolvedAuthors }
  },
  {
    name: 'author-profiles',
    maxAge: CACHE_MAX_AGE_ONE_DAY,
    getKey: event => {
      const { authors } = getQuery(event)
      const hash = crypto
        .createHash('md5')
        .update(JSON.stringify(authors ?? 'npmx.dev'))
        .digest('hex')
      return `author-profiles:${hash}`
    },
  },
)

import { PublicUserSessionSchema } from '#shared/schemas/publicUserSession'
import { safeParse } from 'valibot'

export default eventHandlerWithOAuthSession(async (event, _, serverSession) => {
  const result = safeParse(PublicUserSessionSchema, serverSession.data.public)
  if (!result.success) {
    return null
  }

  // A one time redirect to upgrade the previous sessions.
  // Can remove in 2 weeks from merge if we'd like
  if (serverSession.data.oauthSession && serverSession.data?.public?.did) {
    await serverSession.update({
      oauthSession: undefined,
    })
    return {
      ...result.output,
      relogin: true,
    }
  }

  return result.output
})

import * as v from 'valibot'
import { PackageRouteParamsSchema } from '#shared/schemas/package'
import { CACHE_MAX_AGE_ONE_HOUR, ERROR_CALC_INSTALL_SIZE_FAILED } from '#shared/utils/constants'

/**
 * GET /api/registry/install-size/:name or /api/registry/install-size/:name/v/:version
 *
 * Calculate total install size for a package including all dependencies.
 * Handles platform-specific optional dependencies by counting only one representative per group.
 */
export default defineCachedEventHandler(
  async event => {
    // Parse package name and optional version from path segments
    // Supports: /install-size/lodash, /install-size/lodash/v/4.17.21, /install-size/@scope/name, /install-size/@scope/name/v/1.0.0
    const pkgParamSegments = getRouterParam(event, 'pkg')?.split('/') ?? []

    const { rawPackageName, rawVersion } = parsePackageParams(pkgParamSegments)

    try {
      const { packageName, version: requestedVersion } = v.parse(PackageRouteParamsSchema, {
        packageName: decodeURIComponent(rawPackageName),
        version: rawVersion,
      })

      // If no version specified, resolve to latest using fast-npm-meta (lightweight)
      let version: string | undefined = requestedVersion
      if (!version) {
        const latestVersion = await fetchLatestVersionWithFallback(packageName)
        if (!latestVersion) {
          throw createError({
            statusCode: 404,
            message: 'No latest version found',
          })
        }
        version = latestVersion
      }

      return await calculateInstallSize(packageName, version)
    } catch (error: unknown) {
      handleApiError(error, {
        statusCode: 502,
        message: ERROR_CALC_INSTALL_SIZE_FAILED,
      })
    }
  },
  {
    maxAge: CACHE_MAX_AGE_ONE_HOUR,
    swr: true,
    getKey: event => {
      const pkg = getRouterParam(event, 'pkg') ?? ''
      return `install-size:v1:${pkg.replace(/\/+$/, '').trim()}`
    },
  },
)

import * as v from 'valibot'
import { Client, toDatetimeString } from '@atproto/lex'
import * as dev from '#shared/types/lexicons/dev'
import type { UriString } from '@atproto/lex'
import { LIKES_SCOPE } from '#shared/utils/constants'
import { PackageLikeBodySchema } from '#shared/schemas/social'
import { throwOnMissingOAuthScope } from '#server/utils/atproto/oauth'

export default eventHandlerWithOAuthSession(async (event, oAuthSession) => {
  const loggedInUsersDid = oAuthSession?.did.toString()

  if (!oAuthSession || !loggedInUsersDid) {
    throw createError({ statusCode: 401, statusMessage: 'Unauthorized' })
  }

  //Checks if the user has a scope to like packages
  await throwOnMissingOAuthScope(oAuthSession, LIKES_SCOPE)

  const body = v.parse(PackageLikeBodySchema, await readBody(event))

  const likesUtil = new PackageLikesUtils()

  // Checks to see if the user has liked the package already
  const likesResult = await likesUtil.getLikes(body.packageName, loggedInUsersDid)
  if (likesResult.userHasLiked) {
    return likesResult
  }

  const subjectRef = PACKAGE_SUBJECT_REF(body.packageName)
  const client = new Client(oAuthSession)

  const like = dev.npmx.feed.like.$build({
    createdAt: toDatetimeString(new Date()),
    subjectRef: subjectRef as UriString,
  })

  const result = await client.create(dev.npmx.feed.like, like)
  if (!result) {
    throw createError({
      status: 500,
      message: 'Failed to create a like',
    })
  }

  return await likesUtil.likeAPackageAndReturnLikes(body.packageName, loggedInUsersDid, result.uri)
})

import * as v from 'valibot'
import { Client } from '@atproto/lex'
import * as dev from '#shared/types/lexicons/dev'
import { PackageLikeBodySchema } from '#shared/schemas/social'
import { throwOnMissingOAuthScope } from '#server/utils/atproto/oauth'

export default eventHandlerWithOAuthSession(async (event, oAuthSession) => {
  const loggedInUsersDid = oAuthSession?.did.toString()

  if (!oAuthSession || !loggedInUsersDid) {
    throw createError({ statusCode: 401, statusMessage: 'Unauthorized' })
  }

  //Checks if the user has a scope to like packages
  await throwOnMissingOAuthScope(oAuthSession, LIKES_SCOPE)

  const body = v.parse(PackageLikeBodySchema, await readBody(event))

  const likesUtil = new PackageLikesUtils()

  const getTheUsersLikedRecord = await likesUtil.getTheUsersLikedRecord(
    body.packageName,
    loggedInUsersDid,
  )

  if (getTheUsersLikedRecord) {
    const client = new Client(oAuthSession)

    await client.delete(dev.npmx.feed.like, {
      rkey: getTheUsersLikedRecord.rkey,
    })
    const result = await likesUtil.unlikeAPackageAndReturnLikes(body.packageName, loggedInUsersDid)
    return result
  } else {
    // Always unlike in the cache if this endpoint is called. May be a mismatch
    await likesUtil.setUnlikeInCache(body.packageName, loggedInUsersDid)
  }

  console.warn(
    `User ${loggedInUsersDid} tried to unlike a package ${body.packageName} but it was not liked by them.`,
  )

  return await likesUtil.getLikes(body.packageName, loggedInUsersDid)
})

import * as v from 'valibot'
import { PackageRouteParamsSchema } from '#shared/schemas/package'
import { PACKAGE_SUBJECT_REF } from '#shared/utils/constants'
import { getTopLikedRank } from '#server/utils/likes-leaderboard'

/**
 * GET /api/social/likes/:name
 *
 * Gets the likes for a npm package on npmx
 */
export default eventHandlerWithOAuthSession(async (event, oAuthSession, _) => {
  const pkgParamSegments = getRouterParam(event, 'pkg')?.split('/') ?? []
  const { rawPackageName } = parsePackageParams(pkgParamSegments)

  if (!rawPackageName) {
    throw createError({
      status: 400,
      message: 'package name not provided',
    })
  }

  try {
    const { packageName } = v.parse(PackageRouteParamsSchema, {
      packageName: decodeURIComponent(rawPackageName),
    })

    const likesUtil = new PackageLikesUtils()
    const [likes, topLikedRank] = await Promise.all([
      likesUtil.getLikes(packageName, oAuthSession?.did.toString()),
      getTopLikedRank(event, PACKAGE_SUBJECT_REF(packageName)),
    ])

    return {
      ...likes,
      topLikedRank,
    }
  } catch (error: unknown) {
    handleApiError(error, {
      statusCode: 502,
      message: 'Failed to get likes',
    })
  }
})

