export default defineEventHandler(async event => {
  const identifier = getRouterParam(event, 'identifier')
  if (!identifier) {
    throw createError({
      status: 400,
      message: 'identifier not provided',
    })
  }

  const profileUtil = new ProfileUtils()
  const profile = await profileUtil.getProfile(identifier)
  return profile
})

export default defineCachedEventHandler(
  async event => {
    const pkgParam = getRouterParam(event, 'pkg')
    if (!pkgParam) {
      // TODO: throwing 404 rather than 400 as it's cacheable
      throw createError({ statusCode: 404, message: 'Package name is required' })
    }

    const { packageName, version } = parsePackageParam(pkgParam)

    if (!packageName) {
      // TODO: throwing 404 rather than 400 as it's cacheable
      throw createError({ statusCode: 404, message: 'Package name is required' })
    }
    assertValidPackageName(packageName)

    if (!version) {
      // TODO: throwing 404 rather than 400 as it's cacheable
      throw createError({ statusCode: 404, message: 'Package version is required' })
    }

    let generated
    try {
      generated = await generateDocsWithDeno(packageName, version)
    } catch (error) {
      // eslint-disable-next-line no-console
      console.error(`Doc generation failed for ${packageName}@${version}:`, error)
      return {
        package: packageName,
        version,
        html: '',
        toc: null,
        status: 'error',
        message: 'Failed to generate documentation. Please try again later.',
      } satisfies DocsResponse
    }

    if (!generated) {
      return {
        package: packageName,
        version,
        html: '',
        toc: null,
        status: 'missing',
        message: 'Docs are not available for this package. It may not have TypeScript types.',
      } satisfies DocsResponse
    }

    return {
      package: packageName,
      version,
      html: generated.html,
      toc: generated.toc,
      status: 'ok',
    } satisfies DocsResponse
  },
  {
    maxAge: 60 * 60, // 1 hour cache
    swr: true,
    getKey: event => {
      const pkg = getRouterParam(event, 'pkg') ?? ''
      return `docs:v2:${pkg}`
    },
  },
)

import { parse } from 'valibot'
import { Client } from '@atproto/lex'
import * as dev from '#shared/types/lexicons/dev'
import type { NPMXProfile } from '#shared/types/social'
import { ProfileEditBodySchema } from '#shared/schemas/social'

export default eventHandlerWithOAuthSession(async (event, oAuthSession) => {
  const loggedInUsersDid = oAuthSession?.did.toString()

  if (!oAuthSession || !loggedInUsersDid) {
    throw createError({ statusCode: 401, statusMessage: 'Unauthorized' })
  }

  await throwOnMissingOAuthScope(oAuthSession, PROFILE_SCOPE)

  const requestBody = await readBody(event)
  if (requestBody.website && !URL.canParse(requestBody.website)) {
    throw createError({ statusCode: 400, statusMessage: 'Invalid website' })
  }

  const body = parse(ProfileEditBodySchema, requestBody)
  const client = new Client(oAuthSession)

  const profile = dev.npmx.actor.profile.$build({
    displayName: body.displayName,
    ...(body.description
      ? {
          description: body.description,
        }
      : {}),
    ...(body.website
      ? {
          website: body.website as `${string}:${string}`,
        }
      : {}),
  })

  const result = await client.put(dev.npmx.actor.profile, profile, { rkey: 'self' })
  if (!result) {
    throw createError({
      status: 500,
      message: 'Failed to update the profile',
    })
  }

  const profileUtil = new ProfileUtils()
  await profileUtil.updateProfileCache(loggedInUsersDid, body as NPMXProfile)

  return result.validationStatus
})

